using System;

namespace FunscriptToolbox.SubtitlesVerbs.Infra
{
    /// <summary>
    /// The engine of the steps in the main configuration (generated by the code): no engine yet. A step that sends an AI request
    /// with it fails with a configuration error, until an override file gives it a real engine (ex. { "$ref": "AIEngineGemini3Pro" }).
    /// (a step that doesn't send requests with it, ex. manual-input-preparer with TimingRefineEngineNone, works)
    /// </summary>
    [ConfigDoc("No AI engine: the placeholder of the main configuration. A step that sends an AI request with it fails with a configuration error.",
        Advice = "Choose a real engine for the step (✎ on its 'Engine').")]
    public sealed class AIEngineNeedToBeOverriden : AIEngine
    {
        public override AIResponse[] Execute(
            SubtitleGeneratorContext context,
            AIRequest[] requests,
            AIEngineConfigOverride configOverride = null)
        {
            throw new InvalidOperationException(
                "This step has no AI engine: its 'Engine' is still the placeholder of the main configuration (AIEngineNeedToBeOverriden). " +
                "Set a real engine for the step in an override file, ex. \"Engine\": { \"$ref\": \"AIEngineGemini3Pro\" } (or with ✎ in the Config tab).");
        }
    }
}
